import 'package:flutter/material.dart';import 'package:package_info_plus/package_info_plus.dart';import 'package:url_launcher/url_launcher.dart';import 'api.dart';
class UpdateService{static Future<bool>check(BuildContext context)async{try{final r=await Api.get('/config/app-config');if(r['success']!=true)return false;final c=Map<String,dynamic>.from(r['config']);final v=await PackageInfo.fromPlatform();final cur=_v(v.version),latest=_v('${c['latestVersion']??'1.0.0'}'),min=_v('${c['minimumVersion']??'1.0.0'}');final force=cur<min||(c['forceUpdate']==true&&cur<latest);if(latest<=cur&&!force)return false;if(!context.mounted)return false;await showDialog(context:context,barrierDismissible:!force,builder:(d)=>PopScope(canPop:!force,child:AlertDialog(title:Text('${c['updateTitle']??'CampusMate update'}'),content:Text('${c['updateMessage']??'A new version is available.'}'),actions:[if(!force)TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Later')),FilledButton(onPressed:()async{final u=Uri.tryParse('${c['apkUrl']??''}');if(u!=null)await launchUrl(u,mode:LaunchMode.externalApplication);},child:const Text('Update now'))])));return force;}catch(_){return false;}}static int _v(String s){final p=s.split('.').map((x)=>int.tryParse(x)??0).toList();while(p.length<3){p.add(0);}return p[0]*1000000+p[1]*1000+p[2];}}
